$('library').onclick=()=>{if(pending){notify('saveFirst');return}renderLibrary();modal('gallery')};
function renderLibrary(){let nav=$('folders');nav.replaceChildren();for(let [id,name]of [['all',t('all')],['',t('unfiled')],...library.folders.map(f=>[f.id,f.name])]){let b=el('button',folderFilter===id?'active':'',name);b.onclick=()=>{folderFilter=id;renderLibrary()};nav.append(b)}let folder=library.folders.find(f=>f.id===folderFilter);$('folderRename').hidden=!folder;$('folderDelete').hidden=!folder;$('undoLibrary').hidden=!libraryUndo;let list=$('projects');list.replaceChildren();let records=library.projects.filter(p=>folderFilter==='all'||p.folder===folderFilter).sort((a,b)=>new Date(b.updated)-new Date(a.updated));if(!records.length)list.append(el('div','empty',t(folderFilter==='all'?'emptyLibrary':'folderEmpty')));for(let rec of records){let card=el('article','card'),preview=el('canvas','card-preview'),body=el('div','card-body');preview.setAttribute('aria-label',rec.name);card.append(preview,body);thumbnail(preview,rec.state.pieces);body.append(el('div','card-title',rec.name),el('div','card-meta',t('created')+' '+date(rec.created)+'\n'+t('updated')+' '+date(rec.updated)));let actions=el('div','card-buttons');actions.append(button('open',()=>{if(meta.id!==rec.id&&(state.pieces.length||state.trash.length)&&!saveRecord())return;state=E.copy(rec.state);meta={id:rec.id,name:rec.name,created:rec.created,folder:rec.folder};selected=state.pieces[0]?.id;history=[];future=[];pending=null;fit();changed();$('gallery').close()}),button('rename',()=>askName('rename',rec.name,name=>{let next=E.copy(library);next.projects.find(p=>p.id===rec.id).name=name;if(!persistLibrary(next))return false;if(meta.id===rec.id){meta.name=name;autosave();sync()}renderLibrary()})),button('export',()=>exportRecord(rec)),button('delete',()=>{if(!window.confirm(t('deleteProject')))return;libraryUndo=E.copy(library);let next=E.copy(library);next.projects=next.projects.filter(p=>p.id!==rec.id);if(persistLibrary(next))renderLibrary()},'danger'));body.append(actions);let folderSelect=el('select');folderSelect.setAttribute('aria-label',t('folder'));fillFolders(folderSelect,rec.folder);folderSelect.onchange=()=>{let next=E.copy(library);next.projects.find(p=>p.id===rec.id).folder=folderSelect.value;if(persistLibrary(next)){if(meta.id===rec.id){meta.folder=folderSelect.value;autosave()}renderLibrary()}};body.append(folderSelect);list.append(card)}}
$('newFolder').onclick=()=>askName('newFolder','',name=>{let next=E.copy(library);let folder={id:E.id(),name};next.folders.push(folder);if(!persistLibrary(next))return false;folderFilter=folder.id;renderLibrary()});$('folderRename').onclick=()=>{let f=library.folders.find(f=>f.id===folderFilter);if(f)askName('folderName',f.name,name=>{let next=E.copy(library);next.folders.find(k=>k.id===f.id).name=name;if(!persistLibrary(next))return false;renderLibrary()})};$('folderDelete').onclick=()=>{if(!window.confirm(t('removeFolder')))return;libraryUndo=E.copy(library);let next=E.copy(library);next.folders=next.folders.filter(f=>f.id!==folderFilter);next.projects.forEach(p=>{if(p.folder===folderFilter)p.folder=''});if(persistLibrary(next)){if(meta.folder===folderFilter){meta.folder='';autosave()}folderFilter='all';renderLibrary()}};$('undoLibrary').onclick=()=>{if(libraryUndo&&persistLibrary(libraryUndo)){libraryUndo=null;renderLibrary()}};
function exportRecord(rec){let blob=new Blob([JSON.stringify({format:'Paper Room',version:2,project:rec},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=(rec.name||'paper-room').replace(/[^\p{L}\p{N}\s_-]/gu,'').slice(0,70)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('exported')}
// Exporting the current draft remains available even when browser storage is full.
const exportDraft=button('export',()=>exportRecord({id:meta.id,name:getName(),created:meta.created,updated:new Date().toISOString(),state:E.copy(state),folder:meta.folder}),'quiet');exportDraft.id='exportDraft';exportDraft.dataset.t='export';$('save').after(exportDraft);
$('import').onclick=()=>$('fileInput').click();$('fileInput').onchange=async()=>{let file=$('fileInput').files[0];if(!file)return;try{if(file.size>12*1024*1024)throw Error();let data=JSON.parse(await file.text());if(data.format!=='Paper Room'||data.version!==2||!E.validate(data.project?.state))throw Error();let rec={id:E.id(),name:String(data.project.name||t('untitled')).slice(0,80),created:Number.isFinite(Date.parse(data.project.created))?data.project.created:new Date().toISOString(),updated:new Date().toISOString(),folder:'',state:data.project.state};let next=E.copy(library);next.projects.unshift(rec);if(persistLibrary(next)){folderFilter='all';renderLibrary()}}catch{notify('importError');alert(t('importError'))}finally{$('fileInput').value=''}};
function trashAction(ids,restorePieces){if(!ids.length)return;checkpoint();let entries=state.trash.filter(v=>ids.includes(v.id));if(restorePieces){for(let entry of entries)state.pieces.push(E.copy(entry.piece));selected=entries.at(-1)?.piece.id}state.trash=state.trash.filter(v=>!ids.includes(v.id));changed();renderTrash();notify(restorePieces?'restored':'deleted')}
$('bin').onclick=()=>{if(pending){notify('saveFirst');return}renderTrash();modal('trashDialog')};function renderTrash(){let list=$('trashCards');list.replaceChildren();$('restoreAll').disabled=!state.trash.length;$('deleteAll').disabled=!state.trash.length;if(!state.trash.length)list.append(el('div','empty',t('emptyBin')));for(let entry of state.trash){let card=el('article','card'),preview=el('canvas','card-preview'),body=el('div','card-body');card.append(preview,body);thumbnail(preview,[entry.piece]);body.append(el('div','card-title',entry.piece.name),el('div','card-meta',date(entry.deleted)));let actions=el('div','card-buttons');actions.append(button('restore',()=>trashAction([entry.id],true)),button('delete',()=>trashAction([entry.id],false),'danger'));body.append(actions);list.append(card)}}$('restoreAll').onclick=()=>trashAction(state.trash.map(v=>v.id),true);$('deleteAll').onclick=()=>trashAction(state.trash.map(v=>v.id),false);
window.addEventListener('keydown',e=>{let dialog=document.querySelector('dialog[open]');if(dialog)return;let typing=['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveDialog();return}if(typing)return;if(e.code==='Space'){e.preventDefault();commit()}if(e.key==='Escape')cancel();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click()}});
window.addEventListener('beforeunload',()=>{let stable=pending?.before?.state||state;write(DRAFT,{state:stable,meta})});
